        "Липницької ЗОШ І-ІІІ ступенів",
        "виступають класні керівники. Якщо виникають питання щодо коду доступу, ресурсу, платформи того чи іншого завдання/уроку/предмету, їх можна оперативно вирішити безпосередньо під час спілкування з класними керівниками через визначений на батьківських зборах кожного класу канал зворотного зв\"язку (viber, Skype, Telegram, Facebook, email тощо). Розклад дистанційних уроків такий, як і розклад очних уроків. Просимо всіх здобувачів освіти та вчителів дотримуватися розкладу уроків та розкладу часу проведення уроків згідно з визначеним режимом школи!",
