        "органи самоврядування працівників закладу освіти (профспілковий комітет);",
        "·",
        "органи самоврядування здобувачів освіти (учнівський парламент);",
        "·",
        "органи батьківського самоврядування (батьківький комітет);",
        "·",
        "інші органи громадського самоврядування учасників освітнього процесу.",
        "Вищим колегіальним органом громадського самоврядування закладу освіти є загальні збори (конференція) колективу закладу освіти.",
        "Повноваження, відповідальність, засади формування та діяльності органів громадського самоврядування визначаються спеціальними законами та установчими документами закладу освіти.",
