        "ВИКЛЮЧНО з використанням електронних сервісів: програмно-апаратного комплексу «Автоматизований інформаційний комплекс освітнього менеджменту» (АІКОМ) або засобами Єдиного державного вебпорталу електронних послуг (Портал Дія).",
        "Відповідно до наказу Міністерства освіти і  науки України «Про затвердження Змін до Порядку зарахування, відрахування та переведення учнів до державних та комунальних закладів освіти для здобуття повної загальної середньої освіти, заява про зарахування дитини до школи може бути подана одним із батьків або повнолітньою особою:",
